#!/usr/bin/env python3
"""Writes json-protocol.json: ArduPilot JSON SITL protocol oracle (TASK-041).

Downloads libraries/SITL/SIM_JSON.{h,cpp} and the JSON example readme at the
pinned ArduPilot commit, records their SHA-256 (sources are GPL and are not
copied into this repository), and writes golden servo packets packed with
Python struct ('<HHI16H' / '<HHI32H', little-endian as on SITL hosts) plus a
reply line formatted with '%.9f'. Independent of the TypeScript encoder.
Usage (repository root): python3 tests/fixtures/sitl/generate.py
"""
import hashlib
import json
import math
import struct
import urllib.request
from pathlib import Path

COMMIT = "8ab6afde107a91df1b5f60ade8f333cb8a61b190"
FILES = ["libraries/SITL/SIM_JSON.h", "libraries/SITL/SIM_JSON.cpp", "libraries/SITL/examples/JSON/readme.md"]


def fetch(path):
    url = f"https://raw.githubusercontent.com/ArduPilot/ardupilot/{COMMIT}/{path}"
    with urllib.request.urlopen(url, timeout=60) as response:
        return response.read()


upstream = []
sources = {}
for path in FILES:
    data = fetch(path)
    sources[path] = data.decode()
    upstream.append({"path": path, "sha256": hashlib.sha256(data).hexdigest(), "bytes": len(data)})

# Facts read from the pinned sources; asserted so a different commit fails loudly.
header = sources["libraries/SITL/SIM_JSON.h"]
assert "uint16_t magic = 18458" in header and "uint16_t magic = 29569" in header
assert "uint16_t control_port = 9002" in header
assert "if (state.timestamp_s < last_timestamp_s)" in sources["libraries/SITL/SIM_JSON.cpp"]
assert "deltat < 0.1" in sources["libraries/SITL/SIM_JSON.cpp"]

pwm16 = [1100 + 50 * i for i in range(16)]
pwm32 = [1000 + 25 * i for i in range(32)]
servo = {
    "packet16": {"frameRateHz": 400, "frameCount": 7, "pwmUs": pwm16,
                 "hex": struct.pack("<HHI16H", 18458, 400, 7, *pwm16).hex()},
    "packet32": {"frameRateHz": 1200, "frameCount": 4294967295, "pwmUs": pwm32,
                 "hex": struct.pack("<HHI32H", 29569, 1200, 4294967295, *pwm32).hex()},
    "invalid": [
        {"why": "wrong magic", "hex": struct.pack("<HHI16H", 18459, 400, 7, *pwm16).hex()},
        {"why": "16-channel magic with 32-channel length", "hex": struct.pack("<HHI32H", 18458, 400, 7, *pwm32).hex()},
        {"why": "truncated", "hex": struct.pack("<HHI16H", 18458, 400, 7, *pwm16)[:-1].hex()},
    ],
}

q = [0.9, 0.1, -0.2, 0.3]
norm = math.sqrt(sum(v * v for v in q))
state = {
    "timestampS": 12.3456789, "gyroBodyRadS": [0.01, -0.02, 0.5], "accelBodyMps2": [0.1, -0.2, -9.80665],
    "positionNedM": [1234.5678, -98.7654321, -50.25], "velocityNedMps": [1.5, -0.25, 0.125],
    "quaternionWxyz": q, "windNedMps": [3.2, 0.0, -0.7],
}


def vec(values, scale=1.0):
    return ",".join("%.9f" % (v * scale) for v in values)


line = ('\n{"timestamp":%.9f,"imu":{"gyro":[%s],"accel_body":[%s]},"position":[%s],"velocity":[%s],'
        '"quaternion":[%s],"velocity_wind":[%s]}\n') % (
    state["timestampS"], vec(state["gyroBodyRadS"]), vec(state["accelBodyMps2"]), vec(state["positionNedM"]),
    vec(state["velocityNedMps"]), vec(q, 1 / norm), vec(state["windNedMps"]))

fixture = {
    "description": "ArduPilot JSON SITL protocol oracle (TASK-041); generated by tests/fixtures/sitl/generate.py",
    "ardupilotCommit": COMMIT,
    "upstream": upstream,
    "defaults": {"physicsUdpPort": 9002, "maxTimestampStepS": 0.1, "magic16": 18458, "magic32": 29569,
                 "endianness": "little (SITL host order; x86-64/aarch64 builds)"},
    "servo": servo,
    "state": state,
    "expectedLine": line,
    "readmeExampleLine": '\n{"timestamp":2500,"imu":{"gyro":[0,0,0],"accel_body":[0,0,0]},"position":[0,0,0],"attitude":[0,0,0],"velocity":[0,0,0]}\n',
    "servoMapping": "Motor channel order and MOT_PWM_MIN/MAX are vehicle parameters; the backend takes them as explicit configuration (default 1000/2000 us) rather than inferring them from upstream.",
}
out = Path(__file__).with_name("json-protocol.json")
out.write_text(json.dumps(fixture, indent=2) + "\n")
print(f"wrote {out}")
